CREATE TABLE IF NOT EXISTS people (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name STRING NOT NULL, email STRING NOT NULL UNIQUE, affiliation STRING NOT NULL CHECK (affiliation IN ('Student','Faculty','Alumni','Industry')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS startups (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name STRING NOT NULL UNIQUE, domain STRING NOT NULL CHECK (domain IN ('Artificial Intelligence','Healthcare','FinTech','AgriTech','Cybersecurity','Green Energy','Other')), description STRING NOT NULL DEFAULT '', stage STRING NOT NULL DEFAULT 'ideation' CHECK (stage IN ('ideation','validation','incubation','acceleration','commercialization')), founded_on DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS founders (startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, person_id UUID NOT NULL REFERENCES people(id), role STRING NOT NULL DEFAULT 'Founder', PRIMARY KEY (startup_id,person_id));
CREATE TABLE IF NOT EXISTS mentors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), person_id UUID NOT NULL UNIQUE REFERENCES people(id), expertise STRING NOT NULL, organization STRING NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS mentor_assignments (startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, mentor_id UUID NOT NULL REFERENCES mentors(id), assigned_on DATE NOT NULL DEFAULT current_date(), PRIMARY KEY (startup_id,mentor_id));
CREATE TABLE IF NOT EXISTS stage_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, stage STRING NOT NULL CHECK (stage IN ('ideation','validation','incubation','acceleration','commercialization')), changed_on TIMESTAMPTZ NOT NULL DEFAULT now(), notes STRING NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS evaluations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, mentor_id UUID NOT NULL REFERENCES mentors(id), metric STRING NOT NULL, score INT NOT NULL CHECK (score BETWEEN 1 AND 10), notes STRING NOT NULL DEFAULT '', evaluated_on DATE NOT NULL DEFAULT current_date());
CREATE TABLE IF NOT EXISTS investors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name STRING NOT NULL UNIQUE, organization STRING NOT NULL DEFAULT '', email STRING NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS pitch_meetings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, investor_id UUID NOT NULL REFERENCES investors(id), scheduled_at TIMESTAMPTZ NOT NULL, outcome STRING NOT NULL DEFAULT 'Scheduled' CHECK (outcome IN ('Scheduled','Interested','Declined','Funded')), notes STRING NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS investments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, investor_id UUID NOT NULL REFERENCES investors(id), round_name STRING NOT NULL, amount DECIMAL(18,2) NOT NULL CHECK (amount > 0), invested_on DATE NOT NULL, UNIQUE(startup_id,investor_id,round_name));
CREATE TABLE IF NOT EXISTS events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title STRING NOT NULL, event_type STRING NOT NULL CHECK (event_type IN ('Workshop','Hackathon','Training','Demo Day','Networking')), starts_at TIMESTAMPTZ NOT NULL, venue STRING NOT NULL DEFAULT '', description STRING NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS event_attendance (event_id UUID NOT NULL REFERENCES events(id) ON DELETE CASCADE, startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, PRIMARY KEY(event_id,startup_id));
CREATE TABLE IF NOT EXISTS patents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, title STRING NOT NULL, application_number STRING NOT NULL UNIQUE, status STRING NOT NULL CHECK (status IN ('Filed','Published','Granted')), filed_on DATE NOT NULL);
CREATE TABLE IF NOT EXISTS publications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, title STRING NOT NULL, venue STRING NOT NULL, published_on DATE NOT NULL, doi STRING UNIQUE);
CREATE TABLE IF NOT EXISTS grants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), startup_id UUID NOT NULL REFERENCES startups(id) ON DELETE CASCADE, provider STRING NOT NULL, program STRING NOT NULL, amount DECIMAL(18,2) NOT NULL CHECK (amount > 0), awarded_on DATE NOT NULL);
CREATE INDEX IF NOT EXISTS startups_domain_stage_idx ON startups(domain,stage);
CREATE INDEX IF NOT EXISTS evaluations_startup_date_idx ON evaluations(startup_id,evaluated_on DESC);
CREATE INDEX IF NOT EXISTS investments_startup_idx ON investments(startup_id);
CREATE INDEX IF NOT EXISTS events_starts_idx ON events(starts_at);
